SET XACT_ABORT ON;SET QUOTED_IDENTIFIER ON;
IF SCHEMA_ID('tuyen_sinh') IS NULL EXEC('CREATE SCHEMA tuyen_sinh');
GO
DECLARE @Sql nvarchar(max)=N'';
SELECT @Sql+=N'ALTER TABLE he_thong.TaiKhoanDangNhap DROP CONSTRAINT '+QUOTENAME(name)+';' FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID('he_thong.TaiKhoanDangNhap') AND definition LIKE '%VaiTro%';
IF @Sql<>N'' EXEC(@Sql);
ALTER TABLE he_thong.TaiKhoanDangNhap WITH CHECK ADD CONSTRAINT CK_TaiKhoan_VaiTro CHECK(VaiTro IN('ADMIN','LANH_DAO','CAN_BO','GIANG_VIEN','USER','THI_SINH'));
IF OBJECT_ID('tuyen_sinh.NhanDang','U') IS NULL CREATE TABLE tuyen_sinh.NhanDang(MaNguoi bigint PRIMARY KEY REFERENCES danh_muc.Nguoi(MaNguoi),MaGiayToBam char(64) NOT NULL UNIQUE,GiayToMaHoa nvarchar(1000) NOT NULL);
GO
IF OBJECT_ID('tuyen_sinh.DotTuyen','U') IS NULL CREATE TABLE tuyen_sinh.DotTuyen(
 MaDot int IDENTITY PRIMARY KEY,KyHieu varchar(30) NOT NULL UNIQUE,TenDot nvarchar(200) NOT NULL,
 MoHoSo datetime2 NOT NULL,DongHoSo datetime2 NOT NULL,HanThamDinh datetime2 NOT NULL,HanBoSung datetime2 NOT NULL,NgayThi datetime2 NOT NULL,NgayCongBo datetime2 NOT NULL,HanPhucKhao datetime2 NOT NULL,HanNhapHoc datetime2 NOT NULL,
 TrangThai varchar(30) NOT NULL DEFAULT 'NHAP' CHECK(TrangThai IN('NHAP','DANG_MO','DA_DONG','CHO_DUYET','CONG_BO')),Revision rowversion,
 CHECK(DongHoSo>MoHoSo AND HanThamDinh>=DongHoSo AND HanBoSung>=DongHoSo AND NgayThi>=DongHoSo AND NgayCongBo>=NgayThi AND HanPhucKhao>=NgayCongBo AND HanNhapHoc>=HanPhucKhao));
IF OBJECT_ID('tuyen_sinh.ChiTieu','U') IS NULL CREATE TABLE tuyen_sinh.ChiTieu(
 MaChiTieu int IDENTITY PRIMARY KEY,MaDot int NOT NULL REFERENCES tuyen_sinh.DotTuyen(MaDot),MaNganh int NOT NULL REFERENCES danh_muc.Nganh(MaNganh),TrinhDo varchar(20) NOT NULL CHECK(TrinhDo IN('THAC_SI','TIEN_SI')),
 PhuongThuc varchar(20) NOT NULL CHECK(PhuongThuc IN('THI_TUYEN','XET_TUYEN','TUYEN_THANG')),SoLuong int NOT NULL CHECK(SoLuong BETWEEN 1 AND 100000),LePhi int NOT NULL CHECK(LePhi>=0),PhiNhapHoc int NOT NULL CHECK(PhiNhapHoc>=0),GpaToiThieu decimal(4,2) NOT NULL CHECK(GpaToiThieu BETWEEN 0 AND 10),
 HeSoCoSo decimal(6,3) NOT NULL CHECK(HeSoCoSo BETWEEN 0 AND 100),HeSoChuyenNganh decimal(6,3) NOT NULL CHECK(HeSoChuyenNganh BETWEEN 0 AND 100),HeSoNgoaiNgu decimal(6,3) NOT NULL CHECK(HeSoNgoaiNgu BETWEEN 0 AND 100),HeSoUuTien decimal(6,3) NOT NULL CHECK(HeSoUuTien BETWEEN 0 AND 100),DiemSan decimal(8,3) NOT NULL CHECK(DiemSan>=0),TieuChiPhu varchar(20) NOT NULL CHECK(TieuChiPhu IN('GPA','NGOAI_NGU','CO_SO')),TaiLieuBatBuoc nvarchar(2000) NOT NULL CHECK(ISJSON(TaiLieuBatBuoc)=1),Revision rowversion,UNIQUE(MaDot,MaNganh,TrinhDo,PhuongThuc));
IF OBJECT_ID('tuyen_sinh.ChuanNgoaiNgu','U') IS NULL CREATE TABLE tuyen_sinh.ChuanNgoaiNgu(MaChuan int IDENTITY PRIMARY KEY,MaChiTieu int NOT NULL REFERENCES tuyen_sinh.ChiTieu(MaChiTieu),TenChungChi nvarchar(100) NOT NULL,DiemToiThieu decimal(6,2) NOT NULL,DiemQuyDoi decimal(4,2) NOT NULL CHECK(DiemQuyDoi BETWEEN 0 AND 10),UNIQUE(MaChiTieu,TenChungChi,DiemToiThieu));
IF OBJECT_ID('tuyen_sinh.NganhDauVao','U') IS NULL CREATE TABLE tuyen_sinh.NganhDauVao(MaQuyTac int IDENTITY PRIMARY KEY,MaChiTieu int NOT NULL REFERENCES tuyen_sinh.ChiTieu(MaChiTieu),TenNganh nvarchar(200) NOT NULL,PhanLoai varchar(20) NOT NULL CHECK(PhanLoai IN('DUNG','GAN','KHONG_PHU_HOP')),MonBoSung nvarchar(1000) NULL,UNIQUE(MaChiTieu,TenNganh));
IF OBJECT_ID('tuyen_sinh.HoSo','U') IS NULL CREATE TABLE tuyen_sinh.HoSo(
 MaHoSo bigint IDENTITY PRIMARY KEY,SoHoSo varchar(50) NOT NULL UNIQUE,MaNguoi bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),MaChiTieu int NOT NULL REFERENCES tuyen_sinh.ChiTieu(MaChiTieu),HoSoMaHoa nvarchar(max) NOT NULL,MaGiayToBam char(64) NOT NULL,
 TrangThai varchar(30) NOT NULL DEFAULT 'NHAP' CHECK(TrangThai IN('NHAP','CHO_THANH_TOAN','DA_NOP','CAN_BO_SUNG','DU_DIEU_KIEN','TU_CHOI','DU_KIEN_TRUNG_TUYEN','TRUNG_TUYEN','KHONG_TRUNG_TUYEN','XAC_NHAN_NHAP_HOC','DA_BAN_GIAO')),
 PhanLoaiSoTuyen varchar(30) NULL CHECK(PhanLoaiSoTuyen IN('HOP_LE','THIEU_TAI_LIEU','KHONG_DAT','CAN_KIEM_TRA')),CanhBao nvarchar(2000) NULL,NgayTao datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),NgayNop datetime2 NULL,HanBoSung datetime2 NULL,Revision rowversion,UNIQUE(MaNguoi,MaChiTieu));
IF OBJECT_ID('tuyen_sinh.TaiLieu','U') IS NULL CREATE TABLE tuyen_sinh.TaiLieu(
 MaTaiLieu bigint IDENTITY PRIMARY KEY,MaNguoi bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),MaHoSo bigint NULL REFERENCES tuyen_sinh.HoSo(MaHoSo),LoaiTaiLieu varchar(40) NOT NULL,TenTep nvarchar(255) NOT NULL,KhoaLuuTru varchar(80) NOT NULL UNIQUE,LoaiNoiDung varchar(50) NOT NULL,DungLuong int NOT NULL CHECK(DungLuong BETWEEN 1 AND 10485760),BamSha256 char(64) NOT NULL,
 TrangThaiOcr varchar(30) NOT NULL DEFAULT 'CHO_XU_LY' CHECK(TrangThaiOcr IN('CHO_XU_LY','DANG_XU_LY','HOAN_THANH','CAN_KIEM_TRA','LOI')),DuLieuOcrMaHoa nvarchar(max) NULL,DaDoiChieu bit NOT NULL DEFAULT 0,MaNguoiDoiChieu bigint NULL REFERENCES danh_muc.Nguoi(MaNguoi),NgayTai datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('tuyen_sinh.GiaoDich','U') IS NULL CREATE TABLE tuyen_sinh.GiaoDich(
 MaGiaoDich varchar(50) PRIMARY KEY,MaHoSo bigint NOT NULL REFERENCES tuyen_sinh.HoSo(MaHoSo),LoaiPhi varchar(20) NOT NULL CHECK(LoaiPhi IN('XET_TUYEN','NHAP_HOC')),SoTien int NOT NULL CHECK(SoTien>=0),Kenh varchar(20) NOT NULL CHECK(Kenh IN('VNPAY','NGAN_HANG')),TrangThai varchar(20) NOT NULL DEFAULT 'CHO_TT' CHECK(TrangThai IN('CHO_TT','DA_TT','THAT_BAI')),MaNhaCungCap varchar(100) NULL,MaBienLai varchar(80) NULL,NgayTao datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),NgayThanhToan datetime2 NULL);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('tuyen_sinh.GiaoDich') AND name='UX_GiaoDich_NhaCungCap') CREATE UNIQUE INDEX UX_GiaoDich_NhaCungCap ON tuyen_sinh.GiaoDich(MaNhaCungCap) WHERE MaNhaCungCap IS NOT NULL;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID('tuyen_sinh.GiaoDich') AND name='UX_GiaoDich_ThanhCong') CREATE UNIQUE INDEX UX_GiaoDich_ThanhCong ON tuyen_sinh.GiaoDich(MaHoSo,LoaiPhi) WHERE TrangThai='DA_TT';
IF OBJECT_ID('tuyen_sinh.ThamDinh','U') IS NULL CREATE TABLE tuyen_sinh.ThamDinh(MaThamDinh bigint IDENTITY PRIMARY KEY,MaHoSo bigint NOT NULL REFERENCES tuyen_sinh.HoSo(MaHoSo),MaNguoi bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),KetQua varchar(30) NOT NULL,LyDo nvarchar(2000) NOT NULL,ThoiDiem datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),DiaChiIP varchar(64) NULL);
IF OBJECT_ID('tuyen_sinh.PhongThi','U') IS NULL CREATE TABLE tuyen_sinh.PhongThi(MaPhong int IDENTITY PRIMARY KEY,KyHieu varchar(30) NOT NULL UNIQUE,TenPhong nvarchar(200) NOT NULL,SucChua int NOT NULL CHECK(SucChua BETWEEN 1 AND 1000));
IF OBJECT_ID('tuyen_sinh.CaThi','U') IS NULL CREATE TABLE tuyen_sinh.CaThi(MaCa bigint IDENTITY PRIMARY KEY,MaDot int NOT NULL REFERENCES tuyen_sinh.DotTuyen(MaDot),MaPhong int NOT NULL REFERENCES tuyen_sinh.PhongThi(MaPhong),TenCa nvarchar(200) NOT NULL,BatDau datetime2 NOT NULL,KetThuc datetime2 NOT NULL,HinhThuc varchar(20) NOT NULL CHECK(HinhThuc IN('THI_VIET','PHONG_VAN','DE_CUONG')),TrangThai varchar(20) NOT NULL DEFAULT 'NHAP' CHECK(TrangThai IN('NHAP','CONG_BO','HUY')),Revision rowversion,CHECK(KetThuc>BatDau));
IF OBJECT_ID('tuyen_sinh.PhanCong','U') IS NULL CREATE TABLE tuyen_sinh.PhanCong(MaPhanCong bigint IDENTITY PRIMARY KEY,MaCa bigint NOT NULL REFERENCES tuyen_sinh.CaThi(MaCa),MaCanBo bigint NOT NULL REFERENCES nhan_su.CanBo(MaCanBo),VaiTro varchar(20) NOT NULL CHECK(VaiTro IN('CHU_TICH','THU_KY','COI_THI','CHAM_THI')),UNIQUE(MaCa,MaCanBo));
IF OBJECT_ID('tuyen_sinh.PhanPhong','U') IS NULL CREATE TABLE tuyen_sinh.PhanPhong(MaPhanPhong bigint IDENTITY PRIMARY KEY,MaHoSo bigint NOT NULL UNIQUE REFERENCES tuyen_sinh.HoSo(MaHoSo),MaCa bigint NOT NULL REFERENCES tuyen_sinh.CaThi(MaCa),SoBaoDanh varchar(60) NOT NULL UNIQUE,MaPhach varchar(60) NOT NULL UNIQUE,CoMat bit NULL);
IF OBJECT_ID('tuyen_sinh.KetQua','U') IS NULL CREATE TABLE tuyen_sinh.KetQua(MaHoSo bigint PRIMARY KEY REFERENCES tuyen_sinh.HoSo(MaHoSo),DiemMaHoa nvarchar(2000) NOT NULL,MaNguoiNhap bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),NgayNhap datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),XepHang int NULL,DuKienTrungTuyen bit NULL,Revision rowversion);
IF OBJECT_ID('tuyen_sinh.PhucKhao','U') IS NULL CREATE TABLE tuyen_sinh.PhucKhao(MaPhucKhao bigint IDENTITY PRIMARY KEY,MaHoSo bigint NOT NULL UNIQUE REFERENCES tuyen_sinh.HoSo(MaHoSo),LyDo nvarchar(2000) NOT NULL,TrangThai varchar(20) NOT NULL DEFAULT 'CHO_XU_LY' CHECK(TrangThai IN('CHO_XU_LY','DA_XU_LY','TU_CHOI')),DiemCuMaHoa nvarchar(2000) NOT NULL,DiemMoiMaHoa nvarchar(2000) NULL,MaNguoiXuLy bigint NULL REFERENCES danh_muc.Nguoi(MaNguoi),NgayGui datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),NhanXet nvarchar(2000) NULL);
IF OBJECT_ID('tuyen_sinh.TrinhDuyet','U') IS NULL CREATE TABLE tuyen_sinh.TrinhDuyet(MaDuyet bigint IDENTITY PRIMARY KEY,MaDot int NOT NULL REFERENCES tuyen_sinh.DotTuyen(MaDot),CapDuyet int NOT NULL CHECK(CapDuyet BETWEEN 1 AND 3),MaNguoi bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),ThoiDiem datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),GhiChu nvarchar(1000) NOT NULL,UNIQUE(MaDot,CapDuyet));
IF OBJECT_ID('tuyen_sinh.QuyenDuyet','U') IS NULL CREATE TABLE tuyen_sinh.QuyenDuyet(MaQuyen bigint IDENTITY PRIMARY KEY,MaNguoi bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),CapDuyet int NOT NULL CHECK(CapDuyet BETWEEN 1 AND 3),UNIQUE(MaNguoi,CapDuyet));
IF OBJECT_ID('tuyen_sinh.BanGiao','U') IS NULL CREATE TABLE tuyen_sinh.BanGiao(MaBanGiao bigint IDENTITY PRIMARY KEY,MaHoSo bigint NOT NULL UNIQUE REFERENCES tuyen_sinh.HoSo(MaHoSo),MaHocVien bigint NOT NULL UNIQUE REFERENCES hoc_thuat.HocVien(MaHocVien),MaNguoiThucHien bigint NOT NULL REFERENCES danh_muc.Nguoi(MaNguoi),NgayBanGiao datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),TrangThaiErp varchar(30) NOT NULL DEFAULT 'CHO_CAU_HINH' CHECK(TrangThaiErp IN('CHO_CAU_HINH','CHO_GUI','DA_GUI','LOI')));
IF OBJECT_ID('tuyen_sinh.HangDoiThongBao','U') IS NULL CREATE TABLE tuyen_sinh.HangDoiThongBao(MaThongBao bigint IDENTITY PRIMARY KEY,MaHoSo bigint NOT NULL REFERENCES tuyen_sinh.HoSo(MaHoSo),Kenh varchar(10) NOT NULL CHECK(Kenh IN('EMAIL','SMS')),SuKien varchar(40) NOT NULL,NoiDungMaHoa nvarchar(max) NOT NULL,TrangThai varchar(30) NOT NULL DEFAULT 'CHO_GUI' CHECK(TrangThai IN('CHO_GUI','DANG_GUI','DA_GUI','CHO_CAU_HINH','LOI')),SoLanThu int NOT NULL DEFAULT 0,NgayTao datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF COL_LENGTH('tuyen_sinh.DotTuyen','CongBoDiem') IS NULL ALTER TABLE tuyen_sinh.DotTuyen ADD CongBoDiem bit NOT NULL DEFAULT 0;
GO
CREATE OR ALTER FUNCTION nhan_su.fn_PhamViDonVi(@MaNguoi bigint) RETURNS TABLE AS RETURN
 WITH PhamVi AS(SELECT MaDonVi FROM nhan_su.CanBo WHERE MaNguoi=@MaNguoi AND DangHoatDong=1
 UNION ALL SELECT d.MaDonVi FROM danh_muc.DonVi d JOIN PhamVi p ON d.MaDonViCha=p.MaDonVi)
 SELECT DISTINCT MaDonVi FROM PhamVi;
GO
